sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    /***
     * Param: user name of the requester
     * return: All requests that he is a requester or manager in it . 
     */
    try {

        answer = [];
        var userName = request.queryParams.userName;
        // In case thier is no user-name in Param
        if (!userName) {
            response.setStatus(400); // Error (Bad request)
            return {
                error: 'User-name required..!'
            };
        }

        var equipReqObj = new GlideRecordSecure('x_1850489_mini_p_0_equipments_requests');

        var userObj = new GlideRecord('sys_user');


        userObj.addQuery('user_name', userName);
        userObj.query();


        if(userObj.next()) {
			// var holder = userObj.user_name.toString() ;
			// response.setBody({holder}) ; 
			// return ;  
			// {"requester": userObj.user_name 
			// equipReqObj.get('requester',userObj.sys_id)?equipReqObj.requester.user_name: "ahe"
			// } ;
			equipReqObj.addQuery('requester.user_name', userName).addOrCondition('manager.user_name', userName);
            equipReqObj.query();
            if (equipReqObj.hasNext()) {
                while (equipReqObj.next()) {
                    var returnedObj = {
                        "requester": equipReqObj.requester.user_name.toString(),
                        "manager": equipReqObj.manager.user_name.toString() , 
                        "equipment": equipReqObj.equipment.toString(),
                        "quantity": parseInt(equipReqObj.getValue('quantity')),
                        "total_cost": equipReqObj.total_price
                    };
					// return{result: returnedObj} ; 
                    answer.push(returnedObj);
                }
            }else{
				response.setStatus(200) ; 
				var user_field = userObj.getDisplayValue ;
				return{result: equipReqObj.requester.user_name} ;
			}
		} else {
            response.setStatus(400); // Bad request
            return {
                error: "Invalid requester..! "
            };
        }
		response.setStatus(200) ;  // returned successfully
		response.setBody(answer) ; 
        return {
            message: answer ,
        }; 
    } catch (error) {
        response.setStatus(500);
        return {
            error: error.message 
        };
    }




})(request, response);
